165	        }
166	        // Four eyes: whoever opened a claim cannot also settle it.
167	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
168	            throw new ClaimSettledByOpenerException(id, user);
169	        }
170	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
171	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
172	        if (status == ClaimStatus.SETTLED) {
173	            requireProof(sheetId, person, claim);
174	        }
175	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
176	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
177	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
178	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
179	            BigDecimal due = liveDue(sheetId, claim, figureOf(sheetId, person, claim));
180	            if (limit != null && due != null && due.compareTo(limit) > 0) {
181	                status = ClaimStatus.PENDING;
182	            }
183	        }
184	        RollupService.Snapshot before = rollup.snapshot(sheetId);
185	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
186	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
187	        claim.setStatus(status);
188	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
189	        String number = claim.getNumber();
190	        if (status == ClaimStatus.OPEN) {
191	            number = nextNumber(sheetId, claim.getDate());
192	            claim.setNumber(number);
193	            claim.setOpenedBy(user);
194	        }
195	        Claim saved = claims.saveAndFlush(claim);
196	        log(sheetId, user, person, saved);
197	        String event = switch (status) {
198	            case OPEN -> "CLAIM_OPENED";
199	            case PENDING -> "CLAIM_PENDING";
200	            case SETTLED -> "CLAIM_SETTLED";
201	            case VOID -> "CLAIM_VOIDED";
202	            case DRAFT -> throw new IllegalStateException();
203	        };
204	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
205	        if (status == ClaimStatus.SETTLED) {
206	            watches.notifyWatchers(sheetId, user, person, number);
207	        }
208	        rollup.recordChanges(sheetId, user, before);
209	        return saved;
210	    }
211	
212	    /**
213	     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
214	     * its live figure.
215	     */
216	    @Transactional
217	    public Claim approve(String sheetId, String user, Long id) {
218	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
219	        if (user.equals(claim.getOpenedBy())) {
220	            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
221	        }
222	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
223	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
224	        requireProof(sheetId, person, claim);
225	        RollupService.Snapshot before = rollup.snapshot(sheetId);
226	        String due = settle(sheetId, person, claim);
227	        claim.setStatus(ClaimStatus.SETTLED);
228	        Claim saved = claims.saveAndFlush(claim);
229	        log(sheetId, user, person, saved);
230	        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
231	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
232	        rollup.recordChanges(sheetId, user, before);
233	        return saved;
234	    }
235	
236	    /**
237	     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
238	     * if that statement included it.
239	     */
240	    @Transactional
241	    public Claim reject(String sheetId, String user, Long id, String reason) {
242	        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
243	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
244	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
245	        RollupService.Snapshot before = rollup.snapshot(sheetId);
246	        claim.setStatus(ClaimStatus.OPEN);
247	        Claim saved = claims.saveAndFlush(claim);
248	        log(sheetId, user, person, saved);
249	        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
250	                + " reason=" + reason);
251	        rollup.recordChanges(sheetId, user, before);
252	        return saved;
253	    }
254	
255	    /**
256	     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
257	     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
258	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
259	     * retired before its date, or a user whose role may not reassign.
260	     */
261	    @Transactional
262	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
263	        Claim claim = claims.findForUpdate(id, sheetId)
264	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
265	        if (!roles.may(sheetId, user, "reassign")) {
266	            throw new ClaimReassignForbiddenException(id, user);
267	        }
268	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
269	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
270	        }
271	        if (claim.getPersonId().equals(toPersonId)) {
272	            throw new ClaimReassignException(id, "it is already that person's");
273	        }
274	        periods.requireOpen(sheetId, claim.getDate());
275	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
276	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
277	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
278	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
279	        to.requireClaimable(claim.getDate());
280	        RollupService.Snapshot before = rollup.snapshot(sheetId);
281	        claim.setPersonId(to.getId());
282	        claim.setStated(false, null);
283	        claim.setListed(sheets.nextListed(sheetId));
284	        Claim saved = claims.saveAndFlush(claim);
285	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
286	                + " from=" + from.getName() + " to=" + to.getName());
287	        rollup.recordChanges(sheetId, user, before);
288	        return saved;
289	    }
290	
291	    /**
292	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
293	     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
294	     * date not after today, or a closed period.
295	     */
296	    @Transactional
297	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
298	        Claim claim = claims.findForUpdate(id, sheetId)
299	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
300	        if (claim.getStatus() != ClaimStatus.OPEN) {
301	            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
302	        }
303	        LocalDate today = sheets.today(sheetId);
304	        if (until == null || !until.isAfter(today)) {
305	            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
306	        }
307	        periods.requireOpen(sheetId, claim.getDate());
308	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
309	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
310	        RollupService.Snapshot before = rollup.snapshot(sheetId);
311	        claim.setDeferredUntil(until);
312	        Claim saved = claims.saveAndFlush(claim);
313	        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
314	                + " until=" + until);
315	        rollup.recordChanges(sheetId, user, before);
316	        return saved;
317	    }
318	
319	    /**
320	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
321	     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
322	     * status, a closed period, or a user not a steward.
323	     */
324	    @Transactional
325	    public Claim resettle(String sheetId, String user, Long id) {
326	        Claim claim = claims.findForUpdate(id, sheetId)
327	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
328	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
329	            throw new ClaimResettleForbiddenException(id, user);
330	        }
331	        if (claim.getStatus() != ClaimStatus.SETTLED) {
332	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
333	        }
334	        periods.requireOpen(sheetId, claim.getDate());
335	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
336	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        String old = shownDue(sheetId, person, claim);
339	        BigDecimal figure = dueOf(sheetId, person, claim);
340	        Sheet sheet = settings.get(sheetId);
341	        claim.setSettledDue(claim.isCorrection() ? figure
342	                : sheet.floored(sheet.withLateCharge(figure, true, claim.getDueBy(), claim.getDate()), claim.getDate()));
343	        Claim saved = claims.saveAndFlush(claim);
344	        log(sheetId, user, person, saved);
345	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
346	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
347	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
348	        rollup.recordChanges(sheetId, user, before);
349	        return saved;
350	    }
351	
352	    /**
353	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
354	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
355	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on that date,
356	     * names the claim's number as the one it was split from. Refused for any other status, a closed period, or a user
357	     * whose role may not open a claim.
358	     */
359	    @Transactional
360	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
361	        Claim claim = claims.findForUpdate(id, sheetId)
362	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
363	        if (!roles.may(sheetId, user, "open")) {
364	            throw new ClaimActionForbiddenException(id, user, "open");
365	        }
366	        if (claim.getStatus() != ClaimStatus.OPEN) {
367	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
368	        }
369	        if (claim.isDeferredOn(sheets.today(sheetId))) {
370	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
371	        }
372	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
373	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
374	                    + claim.getAmount().toPlainString());
375	        }
376	        periods.requireOpen(sheetId, claim.getDate());
377	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
378	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
379	        RollupService.Snapshot before = rollup.snapshot(sheetId);
380	        claim.setAmount(claim.getAmount().subtract(amount));
381	        claim.setStated(false, null);
382	        Claim kept = claims.saveAndFlush(claim);
383	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
384	        part.setRoundingDate(kept.getRoundingDate());
385	        part.setDueBy(kept.getDate().plusDays(termsFor(sheetId, person, kept.getDate())));
386	        part.setListed(sheets.nextListed(sheetId));
387	        part.setStatus(ClaimStatus.OPEN);
388	        String number = nextNumber(sheetId, kept.getDate());
389	        part.setNumber(number);
390	        part.setOpenedBy(user);
391	        part.setSplitFrom(kept.getNumber());
392	        Claim saved = claims.saveAndFlush(part);
393	        log(sheetId, user, person, saved);
394	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
395	                + " into=" + number);
396	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
397	        rollup.recordChanges(sheetId, user, before);
398	        return saved;
399	    }
400	
401	    /**
402	     * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED or VOID claim, or a closed period.
403	     */
404	    @Transactional
405	    public Claim addProof(String sheetId, String user, Long id) {
406	        Claim claim = claims.findForUpdate(id, sheetId)
407	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
408	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
409	            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
410	        }
411	        periods.requireOpen(sheetId, claim.getDate());
412	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
413	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
414	        claim.addProof();
415	        Claim saved = claims.saveAndFlush(claim);
416	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
417	                + " proofs=" + saved.getProofs());
418	        return saved;
419	    }
420	
421	    /**
422	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date cannot be
423	     * settled or approved while it has no proof; refused then. A due of n/a is within any threshold.
424	     */
425	    private void requireProof(String sheetId, Person person, Claim claim) {
426	        BigDecimal threshold = settings.get(sheetId).proofThresholdOn(claim.getDate());
427	        if (threshold == null || claim.getProofs() > 0) {
428	            return;
429	        }
430	        BigDecimal due = liveDue(sheetId, claim, figureOf(sheetId, person, claim));
431	        if (due != null && due.compareTo(threshold) > 0) {
432	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
433	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
434	        }
435	    }
436	
437	    /**
438	     * Only a steward voids a SETTLED claim, and only within the days allowed after its settlement (the date of the last
439	     * SETTLED line of its status log) by the sheet's today; refused otherwise.
440	     */
441	    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
442	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
443	            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
444	        }
445	        LocalDate settledOn = logOf(claim).stream()
446	                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
447	                .map(ClaimLog::getDate)
448	                .reduce((first, last) -> last)
449	                .orElse(null);
450	        LocalDate today = sheets.today(sheetId);
451	        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
452	            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
453	                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
454	        }
455	    }
456	
457	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
458	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
459	        Claim claim = claims.findForUpdate(id, sheetId)
460	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
461	        if (claim.getStatus() != ClaimStatus.PENDING) {
462	            throw new ClaimStatusException(id, claim.getStatus(), to);
463	        }
464	        periods.requireOpen(sheetId, claim.getDate());
465	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
466	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
467	        }
468	        return claim;
469	    }
470	
471	    /**
472	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
473	     * the rate on the claim's date) with its late charge, raised to the floor on its date, frozen in (a correction
474	     * freezes its bare figure); with no figure it stays live. Gives the due at the
475	     * end of its audit record.
476	     */
477	    private String settle(String sheetId, Person person, Claim claim) {
478	        BigDecimal figure = figureOf(sheetId, person, claim);
479	        Sheet sheet = settings.get(sheetId);
480	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
481	                : sheet.floored(figure.add(sheet.lateCharge(figure, claim.getDueBy(), claim.getDate())), claim.getDate());
482	        claim.setSettledDue(settledDue);
483	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
484	    }
485	
486	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
487	    private void log(String sheetId, String user, Person person, Claim claim) {
488	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
489	                shownDue(sheetId, person, claim)));
490	    }
491	
492	    /**
493	     * The claim's due as shown: the one fixed when it was settled, else its live due; two decimals, or n/a.
494	     */
495	    private String shownDue(String sheetId, Person person, Claim claim) {
496	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
497	                : liveDue(sheetId, claim, figureOf(sheetId, person, claim));
498	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
499	    }
500	
501	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
502	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
503	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
504	    }
505	
506	    /**
507	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
508	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
509	     * for any other claim.
510	     */
511	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
512	        if (amount.signum() >= 0) {
513	            if (corrects != null) {
514	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
515	            }
516	            return null;
517	        }
518	        if (corrects == null) {
519	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
520	        }
521	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
522	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
523	                .map(Claim::getDate)
524	                .orElseThrow(() -> new ClaimCorrectionException(
525	                        "Claim " + corrects + " is not a settled claim of the same person"));
526	    }
527	
528	    /**
529	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
530	     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
531	     */
532	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
533	        Sheet sheet = settings.get(sheetId);
534	        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
535	                .map(Rate::getPct)
536	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
537	                .orElse(null);
538	    }
539	
540	    /**
541	     * The live due on a figure: the greater of the floor in force on the claim's date and the figure with the late
542	     * charge of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
543	     * on the sheet's today; a correction has neither floor nor late charge); null (n/a) stays null.
544	     */
545	    private BigDecimal liveDue(String sheetId, Claim claim, BigDecimal figure) {
546	        Sheet sheet = settings.get(sheetId);
547	        if (claim.isCorrection()) {
548	            return figure;
549	        }
550	        return sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen()
551	                && !claim.isDeferredOn(sheet.getToday()), claim.getDueBy(), claim.getDate()), claim.getDate());
552	    }
553	
554	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
555	    private static String record(String event, String user, Person person, Claim claim) {
556	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
557	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
558	                + " date=" + claim.getDate();
559	    }
560	
561	    /** The claim's number at the end of an audit record, or nothing when it has none. */
562	    private static String numberOf(String number) {
563	        return number == null ? "" : " number=" + number;
564	    }
565	
566	    /**
567	     * The number a claim dated on the date gets when opened: while the sheet numbers by period, the next in its
568	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
569	     */
570	    private String nextNumber(String sheetId, LocalDate date) {
571	        if (settings.get(sheetId).numbersByPeriod()) {
572	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
573	        }
574	        return String.valueOf(sheets.nextClaimNumber(sheetId));
575	    }
576	
577	    /** The terms of the person on the date: their own, else their grade's on that date, else the sheet's then. */
578	    private int termsFor(String sheetId, Person person, LocalDate date) {
579	        return person.getTerms() != null ? person.getTerms()
580	                : settings.termsFor(sheetId, person.gradeOn(date), date);
581	    }
582	
583	    private LocalDate dateOr(String sheetId, LocalDate date) {
584	        return date != null ? date : sheets.today(sheetId);
585	    }
586	
587	    private static String noteOf(String note) {
588	        return note == null ? "" : note.trim();
589	    }
590	}
