1	package net.officefloor.hq.app.claim;
2	
3	import jakarta.validation.Valid;
4	import jakarta.validation.constraints.NotBlank;
5	import jakarta.validation.constraints.NotNull;
6	import jakarta.validation.constraints.Pattern;
7	import jakarta.validation.constraints.Size;
8	import java.math.BigDecimal;
9	import java.math.RoundingMode;
10	import java.time.LocalDate;
11	import java.util.List;
12	import java.util.Map;
13	import org.springframework.http.HttpStatus;
14	import org.springframework.validation.annotation.Validated;
15	import org.springframework.web.bind.annotation.GetMapping;
16	import org.springframework.web.bind.annotation.PathVariable;
17	import org.springframework.web.bind.annotation.PostMapping;
18	import org.springframework.web.bind.annotation.PutMapping;
19	import org.springframework.web.bind.annotation.RequestBody;
20	import org.springframework.web.bind.annotation.RequestHeader;
21	import org.springframework.web.bind.annotation.RequestMapping;
22	import org.springframework.web.bind.annotation.ResponseStatus;
23	import org.springframework.web.bind.annotation.RestController;
24	
25	/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
26	@RestController
27	@RequestMapping("/api/sheets/{sheetId}")
28	@Validated
29	public class ClaimController {
30	
31	    /**
32	     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
33	     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
34	     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
35	     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
36	     * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
37	     * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
38	     * it has; and the number of the claim it was split off (null unless it was).
39	     */
40	    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
41	            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
42	            LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
43	            int proofs, String splitFrom) {
44	
45	        static ClaimView of(Claim claim, List<ClaimLog> log) {
46	            return new ClaimView(claim.getId(), claim.getPersonId(),
47	                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
48	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
49	                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
50	                    claim.getOpenedBy(), claim.isStated(),
51	                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
52	                    claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
53	                    log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
54	                    claim.getProofs(), claim.getSplitFrom());
55	        }
56	    }
57	
58	    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and its due then (or n/a). */
59	    public record ClaimLogView(ClaimStatus status, String by, LocalDate date, String due) {
60	
61	        static ClaimLogView of(ClaimLog line) {
62	            return new ClaimLogView(line.getStatus(), line.getBy(), line.getDate(), line.getDue());
63	        }
64	    }
65	
66	    /**
67	     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
68	     * number of the claim a correction corrects, blank for any other claim.
69	     */
70	    public record ClaimRequest(
71	            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
72	            LocalDate date,
73	            @Size(max = 1000) String note,
74	            @Size(max = 255) String corrects) {
75	
76	        BigDecimal amountValue() {
77	            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
78	        }
79	
80	        String correctsValue() {
81	            if (corrects == null || corrects.isBlank()) {
82	                return null;
83	            }
84	            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
85	            String trimmed = corrects.trim();
86	            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
87	        }
88	    }
89	
90	    /** The ids of the claims selected to open together. */
91	    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
92	    }
93	
94	    /** The ids of the claims selected to settle together. */
95	    public record BulkSettleRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
96	    }
97	
98	    /** Lines of name,amount,date,note to add as DRAFT claims. */
99	    public record PasteRequest(@NotNull @Size(max = 1000000) String text) {
100	    }
101	
102	    /** How many claims a paste added. */
103	    public record PasteResult(int added) {
104	    }
105	
106	    private final ClaimService service;
107	    private final BulkOpenService bulkOpen;
108	    private final BulkSettleService bulkSettle;
109	    private final PasteClaimsService paste;
110	
111	    public ClaimController(ClaimService service, BulkOpenService bulkOpen, BulkSettleService bulkSettle,
112	            PasteClaimsService paste) {
113	        this.service = service;
114	        this.bulkOpen = bulkOpen;
115	        this.bulkSettle = bulkSettle;
116	        this.paste = paste;
117	    }
118	
119	    /** All the sheet's claims, newest first. */
120	    @GetMapping("/claims")
121	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
122	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
123	        Map<Long, List<ClaimLog>> logs = service.logs(sheetId.trim());
124	        return service.list(sheetId.trim()).stream()
125	                .map(claim -> ClaimView.of(claim, logs.getOrDefault(claim.getId(), List.of())))
126	                .toList();
127	    }
128	
129	    @PostMapping("/people/{personId}/claims")
130	    @ResponseStatus(HttpStatus.CREATED)
131	    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
132	            @PathVariable Long personId,
133	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
134	            @RequestBody @Valid ClaimRequest request) {
135	        return view(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
136	                request.note(), request.correctsValue()));
137	    }
138	
139	    /** Add a DRAFT claim per pasted line, in order; refused as a whole when any line would be. */
140	    @PostMapping("/claims/paste")
141	    public PasteResult paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
142	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
143	            @RequestBody @Valid PasteRequest request) {
144	        return new PasteResult(paste.paste(sheetId.trim(), user.trim(), request.text()));
145	    }
146	
147	    /** Edit a DRAFT claim; refused for any other status. */
148	    @PutMapping("/claims/{id}")
149	    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
150	            @PathVariable Long id,
151	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
152	            @RequestBody @Valid ClaimRequest request) {
153	        return view(service.update(sheetId.trim(), user.trim(), id, request.amountValue(), request.date(),
154	                request.note(), request.correctsValue()));
155	    }
156	
157	    /** Open a DRAFT claim. */
158	    @PostMapping("/claims/{id}/open")
159	    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
160	            @PathVariable Long id,
161	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
