381	export class Claims {
382	  private readonly http = inject(HttpClient);
383	  private readonly session = inject(Session);
384	
385	  readonly personId = input.required<number>();
386	  readonly personName = input.required<string>();
387	  /** The person's claims, newest first. */
388	  readonly claims = input.required<Claim[]>();
389	  /** The person's grades, each from its from-date. */
390	  readonly grades = input.required<PersonGrade[]>();
391	  /** The sheet's rates: a claim's due uses the rate in force on the claim's date of the grade in force then. */
392	  readonly rates = input.required<Rate[]>();
393	  /** The sheet's periods: a claim belongs to the one whose dates contain its date. */
394	  readonly periods = input.required<Period[]>();
395	  /** The sheet's people, in the order they were added: a claim may be reassigned to any of the others. */
396	  readonly people = input<{ id: number; name: string }[]>([]);
397	  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
398	  readonly retiredFrom = input<string | null>(null);
399	  /** The ids of the sheet's claims selected to act on together. */
400	  readonly selected = input<ReadonlySet<number>>(new Set());
401	  /** A claim's checkbox was ticked or cleared. */
402	  readonly selectToggled = output<{ id: number; checked: boolean }>();
403	  /** A claim was added, saved or changed status. */
404	  readonly saved = output<Claim>();
405	
406	  protected readonly amount = signal('');
407	  protected readonly date = signal('');
408	  protected readonly note = signal('');
409	  /** The number of the settled claim a correction (a negative amount) corrects. */
410	  protected readonly corrects = signal('');
411	  /** The id of the claim whose editor is open, or null when the form adds a claim. */
412	  protected readonly editing = signal<number | null>(null);
413	  protected readonly error = signal<string | null>(null);
414	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
415	  private submitting = false;
416	  /** The error of the last status change refused, and the claim it belongs to. */
417	  protected readonly actionError = signal<{ id: number; message: string } | null>(null);
418	  protected readonly actions: { action: ClaimAction; label: string }[] = [
419	    { action: 'open', label: 'Open' },
420	    { action: 'settle', label: 'Settle' },
421	    { action: 'void', label: 'Void' },
422	    { action: 'approve', label: 'Approve' },
423	    { action: 'reject', label: 'Reject' },
424	    { action: 'resettle', label: 'Re-settle' },
425	  ];
426	  /** The people other than this one, whom a claim may be reassigned to. */
427	  protected readonly others = computed(() => this.people().filter((p) => p.id !== this.personId()));
428	  /** The id (as text) of the person picked to reassign each claim to, by claim id. */
429	  protected readonly reassignTo = signal<Record<number, string>>({});
430	  /** The reason typed to reject each PENDING claim, by claim id. */
431	  protected readonly rejectReasons = signal<Record<number, string>>({});
432	  /** The date (yyyy-mm-dd) picked to defer each OPEN claim until, by claim id. */
433	  protected readonly deferDates = signal<Record<number, string>>({});
434	  /** The amount typed to split off each OPEN claim, by claim id. */
435	  protected readonly splitAmounts = signal<Record<number, string>>({});
436	
437	  protected fieldId(field: string): string {
438	    return `claim-form-${field}-${this.personId()}`;
439	  }
440	
441	  /** The due fixed when the claim was settled, else its amount times the rate on its date, or n/a with no rate. */
442	  protected due(claim: Claim): string {
443	    return claimDue(claim, this.rates(), this.grades(), this.session);
444	  }
445	
446	  /** Whether the claim is OPEN and was due by a day before the sheet's today. */
447	  protected overdue(claim: Claim): boolean {
448	    return overdue(claim, this.session.today());
449	  }
450	
451	  /** Whether the claim is deferred on the sheet's today. */
452	  protected deferred(claim: Claim): boolean {
453	    return deferred(claim, this.session.today());
454	  }
455	
456	  /** The name of the period the claim's date falls in, or blank when none. */
457	  protected periodOf(claim: Claim): string {
458	    return periodOn(this.periods(), claim.date)?.name ?? '';
459	  }
460	
461	  /** The closed period the date falls in, or undefined when none does. */
462	  private closedOn(date: string): Period | undefined {
463	    const period = periodOn(this.periods(), date);
464	    return period?.closed ? period : undefined;
465	  }
466	
467	  protected value(event: Event): string {
468	    return (event.target as HTMLInputElement).value;
469	  }
470	
471	  protected checked(event: Event): boolean {
472	    return (event.target as HTMLInputElement).checked;
473	  }
474	
475	  /** Open the claim's editor; only a DRAFT can be edited; to change an OPEN claim, void it and add a new one. */
476	  protected edit(claim: Claim): void {
477	    if (claim.status !== 'DRAFT') {
478	      this.reset();
479	      this.actionError.set({
480	        id: claim.id,
481	        message: `This claim is ${claim.status}: only a DRAFT can be edited. To change an open claim, void it and add a new one.`,
482	      });
483	      return;
484	    }
485	    this.editing.set(claim.id);
486	    this.amount.set(claim.amount);
487	    this.date.set(claim.date);
488	    this.note.set(claim.note);
489	    this.corrects.set(claim.corrects ?? '');
490	    this.error.set(null);
491	    this.actionError.set(null);
492	  }
493	
494	  protected reset(): void {
495	    this.editing.set(null);
496	    this.amount.set('');
497	    this.date.set('');
498	    this.note.set('');
499	    this.corrects.set('');
500	    this.error.set(null);
501	  }
502	
503	  protected setRejectReason(id: number, reason: string): void {
504	    this.rejectReasons.update((all) => ({ ...all, [id]: reason }));
505	    if (this.actionError()?.id === id) this.actionError.set(null);
506	  }
507	
508	  protected setDeferDate(id: number, date: string): void {
509	    this.deferDates.update((all) => ({ ...all, [id]: date }));
510	    if (this.actionError()?.id === id) this.actionError.set(null);
511	  }
512	
513	  /**
514	   * Defer an OPEN claim until the date picked for it; the store refuses a claim not OPEN, a date not after the sheet's
515	   * today, and a closed period.
516	   */
517	  protected async defer(claim: Claim): Promise<void> {
518	    this.actionError.set(null);
519	    const sheet = this.session.sheet();
520	    if (!sheet) return;
521	    const until = (this.deferDates()[claim.id] ?? '').trim();
522	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
523	      this.actionError.set({ id: claim.id, message: 'Pick the date to defer this claim until.' });
524	      return;
525	    }
526	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/defer`;
527	    try {
528	      const saved = await firstValueFrom(this.http.post<Claim>(url, { until }, this.session.headers()));
529	      this.setDeferDate(claim.id, '');
530	      if (this.session.sheet() === sheet) this.saved.emit(saved);
531	    } catch {
532	      const closed = this.closedOn(claim.date);
533	      const today = this.session.today();
534	      const message =
535	        claim.status !== 'OPEN'
536	          ? `This claim is ${claim.status}: only an OPEN claim can be deferred.`
537	          : closed
538	            ? `This claim is dated in the closed period ${closed.name}: it cannot be deferred.`
539	            : today !== null && until <= today
540	              ? `A claim can only be deferred to a date after today (${today}).`
541	              : 'This claim could not be deferred.';
542	      this.actionError.set({ id: claim.id, message });
543	    }
544	  }
545	
546	  /** Add a proof to the claim; the store refuses a SETTLED or VOID claim, and a closed period. */
547	  protected async addProof(claim: Claim): Promise<void> {
548	    this.actionError.set(null);
549	    const sheet = this.session.sheet();
550	    if (!sheet) return;
551	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/proof`;
552	    try {
553	      const saved = await firstValueFrom(this.http.post<Claim>(url, null, this.session.headers()));
554	      if (this.session.sheet() === sheet) this.saved.emit(saved);
555	    } catch {
556	      const closed = this.closedOn(claim.date);
557	      const message =
558	        claim.status === 'SETTLED' || claim.status === 'VOID'
559	          ? `This claim is ${claim.status}: a proof cannot be added to it.`
560	          : closed
561	            ? `This claim is dated in the closed period ${closed.name}: a proof cannot be added to it.`
562	            : 'A proof could not be added to this claim.';
563	      this.actionError.set({ id: claim.id, message });
564	    }
565	  }
566	
567	  protected setSplitAmount(id: number, amount: string): void {
568	    this.splitAmounts.update((all) => ({ ...all, [id]: amount }));
569	    if (this.actionError()?.id === id) this.actionError.set(null);
570	  }
571	
572	  /**
573	   * Split the amount typed for it off an OPEN claim into a new OPEN claim; the store refuses a claim not OPEN or
574	   * deferred, an amount not above 0.00 and below the claim's, a closed period, and a role that may not open a claim.
575	   */
576	  protected async split(claim: Claim): Promise<void> {
577	    this.actionError.set(null);
578	    const sheet = this.session.sheet();
579	    if (!sheet) return;
580	    const amount = (this.splitAmounts()[claim.id] ?? '').trim();
581	    if (!/^\d+(\.\d{1,2})?$/.test(amount)) {
582	      this.actionError.set({ id: claim.id, message: 'Type the amount to split off, with at most two decimals.' });
583	      return;
584	    }
585	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/split`;
586	    try {
587	      const added = await firstValueFrom(this.http.post<Claim>(url, { amount }, this.session.headers()));
588	      this.setSplitAmount(claim.id, '');
589	      if (this.session.sheet() === sheet) this.saved.emit(added);
590	    } catch (e) {
591	      const closed = this.closedOn(claim.date);
592	      const message =
593	        e instanceof HttpErrorResponse && e.status === 403
594	          ? 'Your role may not open a claim, so it may not split one.'
595	          : claim.status !== 'OPEN'
596	            ? `This claim is ${claim.status}: only an OPEN claim can be split.`
597	            : this.deferred(claim)
598	              ? `This claim is deferred until ${claim.deferredUntil}: it cannot be split.`
599	              : closed
600	                ? `This claim is dated in the closed period ${closed.name}: it cannot be split.`
601	                : `The amount split off must be more than 0.00 and less than ${claim.amount}.`;
602	      this.actionError.set({ id: claim.id, message });
603	    }
604	  }
605	
606	  protected setReassignTo(id: number, personId: string): void {
607	    this.reassignTo.update((all) => ({ ...all, [id]: personId }));
608	    if (this.actionError()?.id === id) this.actionError.set(null);
609	  }
610	
611	  /**
612	   * Move a DRAFT, OPEN or PENDING claim to the person picked for it; the store refuses a SETTLED or VOID claim, a
613	   * closed period, a person retired before its date, and a user who is not a steward.
614	   */
615	  protected async reassign(claim: Claim): Promise<void> {
616	    this.actionError.set(null);
617	    const sheet = this.session.sheet();
618	    if (!sheet) return;
619	    const to = this.others().find((p) => String(p.id) === this.reassignTo()[claim.id]);
620	    if (to === undefined) {
621	      this.actionError.set({ id: claim.id, message: 'Pick the person to reassign this claim to.' });
622	      return;
623	    }
624	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/reassign`;
625	    try {
626	      const saved = await firstValueFrom(this.http.post<Claim>(url, { personId: to.id }, this.session.headers()));
627	      this.setReassignTo(claim.id, '');
628	      if (this.session.sheet() === sheet) this.saved.emit(saved);
629	    } catch (e) {
630	      const closed = this.closedOn(claim.date);
631	      const message =
632	        e instanceof HttpErrorResponse && e.status === 403
633	          ? 'Only a steward can reassign a claim.'
634	          : closed
635	            ? `This claim is dated in the closed period ${closed.name}: it cannot be reassigned.`
636	            : claim.status === 'SETTLED' || claim.status === 'VOID'
637	              ? `This claim is ${claim.status}: only a DRAFT, OPEN or PENDING claim can be reassigned.`
638	              : `This claim could not be reassigned to ${to.name}.`;
639	      this.actionError.set({ id: claim.id, message });
640	    }
641	  }
642	
643	  /**
644	   * Open, settle, void, approve, reject or re-settle a claim; the store refuses a change its status, or the user's role, does not
645	   * allow. Rejecting takes the reason typed for the claim.
646	   */
647	  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
648	    this.actionError.set(null);
649	    const sheet = this.session.sheet();
650	    if (!sheet) return;
651	    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
652	    if (action === 'reject' && reason === '') {
653	      this.actionError.set({ id: claim.id, message: 'Type a reason to reject this claim.' });
654	      return;
655	    }
656	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}`;
657	    try {
658	      const body = action === 'reject' ? { reason } : null;
659	      const saved = await firstValueFrom(this.http.post<Claim>(url, body, this.session.headers()));
660	      if (action === 'reject') this.setRejectReason(claim.id, '');
661	      if (this.session.sheet() === sheet) this.saved.emit(saved);
662	    } catch (e) {
663	      const closed = this.closedOn(claim.date);
664	      const message =
665	        e instanceof HttpErrorResponse && e.status === 403
666	          ? action === 'settle'
667	            ? 'Whoever opened this claim cannot also settle it: another user must settle it.'
668	            : action === 'resettle'
669	            ? 'Only a steward can re-settle a claim.'
670	            : action === 'void'
671	            ? claim.status === 'SETTLED'
672	              ? 'Only a steward can void a settled claim.'
673	              : 'Your role is not allowed to void a claim.'
674	            : 'Only a steward can approve or reject a pending claim, and not the one who opened it.'
675	          : closed
676	              ? `This claim is dated in the closed period ${closed.name}: it cannot be ${pastOf[action]}.`
677	              : e instanceof HttpErrorResponse && e.status === 422 && (action === 'settle' || action === 'approve')
678	                ? `This claim's due is above the proof threshold: add a proof before it can be ${pastOf[action]}.`
679	              : action === 'settle' && this.deferred(claim)
680	                ? `This claim is deferred until ${claim.deferredUntil}: it cannot be settled before then.`
681	              : action === 'resettle'
682	                ? `This claim is ${claim.status}: only a SETTLED claim can be re-settled.`
683	              : action === 'void' && claim.status === 'SETTLED'
684	                ? 'A settled claim can only be voided within 7 days of its settlement.'
685	                : `This claim's status does not let it be ${pastOf[action]}.`;
686	      this.actionError.set({ id: claim.id, message });
687	    }
688	  }
689	
690	  protected async submit(event: Event): Promise<void> {
691	    event.preventDefault();
692	    if (this.submitting) return;
693	    this.error.set(null);
694	    const sheet = this.session.sheet();
695	    if (!sheet) return;
696	    const amount = this.amount().trim();
697	    if (!/^-?\d+(\.\d{1,2})?$/.test(amount)) {
698	      this.error.set('Type an amount with at most two decimals; a negative one is a correction.');
699	      return;
700	    }
701	    const corrects = this.corrects().trim();
702	    if (corrects.length > 255) {
703	      this.error.set('Type the number of the settled claim the correction corrects.');
704	      return;
705	    }
706	    const date = this.date().trim();
707	    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
708	      this.error.set('Pick a date for the claim, or leave it blank for today.');
709	      return;
710	    }
711	    const body = { amount, date: date || null, note: this.note(), corrects: corrects || null };
712	    const editing = this.editing();
713	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
714	    this.submitting = true;
715	    try {
716	      const saved = await firstValueFrom(
717	        editing === null
718	          ? this.http.post<Claim>(`${base}/people/${this.personId()}/claims`, body, this.session.headers())
719	          : this.http.put<Claim>(`${base}/claims/${editing}`, body, this.session.headers()),
720	      );
721	      if (this.session.sheet() === sheet) {
722	        this.reset();
723	        this.saved.emit(saved);
724	      }
725	    } catch (e) {
726	      const dated = date || (this.session.today() ?? '');
727	      const closed = this.closedOn(dated);
728	      const retiredFrom = this.retiredFrom();
729	      const why = closed
730	        ? ` Its date is in the closed period ${closed.name}.`
731	        : retiredFrom !== null && dated > retiredFrom
732	          ? ` ${this.personName()} is retired from ${retiredFrom}.`
733	          : editing !== null && e instanceof HttpErrorResponse && e.status === 409
734	          ? ' Only a DRAFT claim can be edited.'
735	          : e instanceof HttpErrorResponse && e.status === 422
736	          ? ' A negative amount is a correction: it must name, by number, a settled claim of this person.'
737	          : '';
738	      this.error.set((editing === null ? 'The claim could not be added.' : 'The claim could not be saved.') + why);
739	    } finally {
740	      this.submitting = false;
741	    }
742	  }
743	}
744	
745	const pastOf: Record<ClaimAction, string> = {
746	  open: 'opened',
747	  settle: 'settled',
748	  void: 'voided',
749	  approve: 'approved',
750	  reject: 'rejected',
751	  resettle: 're-settled',
752	};
